package com.parcelproof;
import jakarta.transaction.Transactional;import org.springframework.security.authentication.*;import org.springframework.security.crypto.password.*;import org.springframework.stereotype.*;import java.time.*;import java.util.*;import java.util.concurrent.ThreadLocalRandom;
@Service class Mapper{UserResponse user(AppUser u){return new UserResponse(u.id,u.fullName,u.email,u.role.name(),u.phone,u.address,u.status.name(),u.vehicleNumber,u.vehicleType==null?null:u.vehicleType.name(),u.availabilityStatus==null?null:u.availabilityStatus.name());}ParcelResponse parcel(Parcel p,boolean otp){return new ParcelResponse(p.id,p.trackingCode,p.senderName,p.senderPhone,p.senderAddress,p.receiverName,p.receiverPhone,p.receiverAddress,p.receiverCity,p.parcelType.name(),p.weight,p.deliveryFee,p.paymentStatus.name(),p.priority.name(),p.status.name(),p.assignedDriver==null?null:p.assignedDriver.id,p.assignedDriver==null?null:p.assignedDriver.fullName,p.customer==null?null:p.customer.id,p.customer==null?null:p.customer.fullName,p.pickupDate,p.expectedDeliveryDate,p.deliveredAt,p.otpVerified,otp?p.deliveryOtp:null,p.proofNote,p.proofPhotoPath,p.createdAt);}PublicTrackingResponse pub(Parcel p){return new PublicTrackingResponse(p.trackingCode,p.receiverName,p.receiverCity,p.parcelType.name(),p.priority.name(),p.status.name(),p.expectedDeliveryDate,p.status==ParcelStatus.DELIVERED,p.otpVerified);}TimelineResponse tl(ParcelTimeline t){return new TimelineResponse(t.id,t.status.name(),t.description,t.updatedBy==null?"System":t.updatedBy.fullName,t.locationNote,t.publicVisible,t.createdAt);}}
@Service class AuthService{final UserRepo users;final PasswordEncoder enc;final AuthenticationManager auth;final JwtService jwt;final Mapper map;AuthService(UserRepo u,PasswordEncoder e,AuthenticationManager a,JwtService j,Mapper m){users=u;enc=e;auth=a;jwt=j;map=m;}AuthResponse register(RegisterRequest r){if(users.existsByEmail(r.email().toLowerCase()))throw new RuntimeException("Email already exists");AppUser u=new AppUser();u.fullName=r.fullName();u.email=r.email().toLowerCase();u.password=enc.encode(r.password());u.phone=r.phone();u.address=r.address();u.role=r.role()==null?UserRole.CUSTOMER:r.role();u.status=UserStatus.ACTIVE;users.save(u);return new AuthResponse(jwt.gen(u),map.user(u));}AuthResponse login(LoginRequest r){auth.authenticate(new UsernamePasswordAuthenticationToken(r.email().toLowerCase(),r.password()));AppUser u=users.findByEmail(r.email().toLowerCase()).orElseThrow();return new AuthResponse(jwt.gen(u),map.user(u));}}
@Service class AuditService{final AuditRepo repo;AuditService(AuditRepo r){repo=r;}void log(AppUser u,String a,String t,Long id,String d){repo.save(new AuditLog(u,a,t,id,d));}}
@Service class ParcelService{final ParcelRepo parcels;final UserRepo users;final AttemptRepo attempts;final TimelineRepo timelines;final AuditService audit;final Mapper map;ParcelService(ParcelRepo p,UserRepo u,AttemptRepo a,TimelineRepo t,AuditService au,Mapper m){parcels=p;users=u;attempts=a;timelines=t;audit=au;map=m;}String code(){return "PP"+LocalDate.now().toString().replace("-","")+ThreadLocalRandom.current().nextInt(100000,999999);}String otp(){return ""+ThreadLocalRandom.current().nextInt(100000,999999);}AppUser user(String e){return users.findByEmail(e).orElseThrow();}List<ParcelResponse> list(AppUser c){List<Parcel> l=c.role==UserRole.DRIVER?parcels.findByAssignedDriver(c):c.role==UserRole.CUSTOMER?parcels.findByCustomer(c):parcels.findAll();return l.stream().map(p->map.parcel(p,canOtp(c,p))).toList();}@Transactional ParcelResponse create(ParcelRequest r,AppUser c){if(r.pickupDate()!=null&&r.expectedDeliveryDate().isBefore(r.pickupDate()))throw new RuntimeException("Expected date cannot be before pickup date");Parcel p=new Parcel();do{p.trackingCode=code();}while(parcels.existsByTrackingCode(p.trackingCode));p.deliveryOtp=otp();p.senderName=r.senderName();p.senderPhone=r.senderPhone();p.senderAddress=r.senderAddress();p.receiverName=r.receiverName();p.receiverPhone=r.receiverPhone();p.receiverAddress=r.receiverAddress();p.receiverCity=r.receiverCity();p.parcelType=r.parcelType();p.weight=r.weight();p.deliveryFee=r.deliveryFee();p.paymentStatus=r.paymentStatus();p.priority=r.priority();p.status=ParcelStatus.BOOKED;p.pickupDate=r.pickupDate();p.expectedDeliveryDate=r.expectedDeliveryDate();p.createdBy=c;if(r.customerId()!=null){AppUser cu=users.findById(r.customerId()).orElseThrow();if(cu.role!=UserRole.CUSTOMER)throw new RuntimeException("Selected user is not customer");p.customer=cu;}parcels.save(p);timelines.save(new ParcelTimeline(p,ParcelStatus.BOOKED,"Parcel booked with tracking code "+p.trackingCode,c,true));audit.log(c,"PARCEL_CREATED","Parcel",p.id,"Parcel created");return map.parcel(p,true);}Parcel parcel(Long id){return parcels.findById(id).orElseThrow();}ParcelResponse get(Long id,AppUser c){Parcel p=parcel(id);access(c,p);return map.parcel(p,canOtp(c,p));}PublicTrackingResponse track(String tc){return map.pub(parcels.findByTrackingCode(tc).orElseThrow());}List<TimelineResponse> timeline(Long id,AppUser c){Parcel p=parcel(id);access(c,p);return timelines.findByParcelOrderByCreatedAtAsc(p).stream().map(map::tl).toList();}List<TimelineResponse> publicTimeline(String tc){Parcel p=parcels.findByTrackingCode(tc).orElseThrow();return timelines.findByParcelAndPublicVisibleOrderByCreatedAtAsc(p,true).stream().map(map::tl).toList();}@Transactional ParcelResponse assign(Long id,Long driverId,AppUser c){Parcel p=parcel(id);if(p.status!=ParcelStatus.BOOKED&&p.status!=ParcelStatus.ASSIGNED)throw new RuntimeException("Cannot assign this parcel");AppUser d=users.findById(driverId).orElseThrow();if(d.role!=UserRole.DRIVER||d.status!=UserStatus.ACTIVE)throw new RuntimeException("Driver must be active");p.assignedDriver=d;p.status=ParcelStatus.ASSIGNED;parcels.save(p);timelines.save(new ParcelTimeline(p,ParcelStatus.ASSIGNED,"Driver assigned: "+d.fullName,c,true));audit.log(c,"DRIVER_ASSIGNED","Parcel",p.id,"Driver assigned");return map.parcel(p,true);}@Transactional ParcelResponse status(Long id,ParcelStatus s,String note,AppUser c){Parcel p=parcel(id);staffOrDriver(c,p);if(s==ParcelStatus.DELIVERED)throw new RuntimeException("Use OTP endpoint");p.status=s;parcels.save(p);timelines.save(new ParcelTimeline(p,s,note==null?"Status updated to "+s:note,c,true));audit.log(c,"STATUS_UPDATED","Parcel",p.id,"Status "+s);return map.parcel(p,canOtp(c,p));}@Transactional ParcelResponse fail(Long id,FailedAttemptRequest r,AppUser d){Parcel p=parcel(id);assigned(d,p);DeliveryAttempt a=new DeliveryAttempt();a.parcel=p;a.driver=d;a.attemptNumber=(int)attempts.countByParcel(p)+1;a.attemptStatus=AttemptStatus.FAILED;a.failureReason=r.failureReason();a.notes=r.notes();a.proofPhotoPath=r.proofPhotoPath();attempts.save(a);p.status=ParcelStatus.FAILED_ATTEMPT;parcels.save(p);timelines.save(new ParcelTimeline(p,ParcelStatus.FAILED_ATTEMPT,"Delivery failed: "+r.failureReason(),d,true));return map.parcel(p,false);}@Transactional ParcelResponse verify(Long id,VerifyDeliveryRequest r,AppUser d){Parcel p=parcel(id);assigned(d,p);if(!p.deliveryOtp.equals(r.otp()))throw new RuntimeException("Invalid OTP");DeliveryAttempt a=new DeliveryAttempt();a.parcel=p;a.driver=d;a.attemptNumber=(int)attempts.countByParcel(p)+1;a.attemptStatus=AttemptStatus.SUCCESSFUL;a.otpVerified=true;a.notes=r.proofNote();a.proofPhotoPath=r.proofPhotoPath();attempts.save(a);p.status=ParcelStatus.DELIVERED;p.otpVerified=true;p.proofNote=r.proofNote();p.proofPhotoPath=r.proofPhotoPath();p.deliveredAt=LocalDateTime.now();parcels.save(p);timelines.save(new ParcelTimeline(p,ParcelStatus.DELIVERED,"Delivered with OTP verification",d,true));return map.parcel(p,false);}boolean canOtp(AppUser c,Parcel p){return c.role==UserRole.ADMIN||c.role==UserRole.DISPATCHER||(p.customer!=null&&p.customer.id.equals(c.id));}void access(AppUser c,Parcel p){if(c.role==UserRole.ADMIN||c.role==UserRole.DISPATCHER)return;if(c.role==UserRole.DRIVER&&p.assignedDriver!=null&&p.assignedDriver.id.equals(c.id))return;if(c.role==UserRole.CUSTOMER&&p.customer!=null&&p.customer.id.equals(c.id))return;throw new RuntimeException("Access denied");}void staffOrDriver(AppUser c,Parcel p){if(c.role==UserRole.ADMIN||c.role==UserRole.DISPATCHER)return;assigned(c,p);}void assigned(AppUser d,Parcel p){if(d.role!=UserRole.DRIVER||p.assignedDriver==null||!p.assignedDriver.id.equals(d.id))throw new RuntimeException("Driver can update only assigned parcels");}}
@Service class DashboardService{final ParcelRepo parcels;final UserRepo users;final AttemptRepo attempts;DashboardService(ParcelRepo p,UserRepo u,AttemptRepo a){parcels=p;users=u;attempts=a;}Map<String,Object> admin(){Map<String,Object> m=new LinkedHashMap<>();long total=parcels.count(),del=parcels.countByStatus(ParcelStatus.DELIVERED);m.put("totalParcels",total);m.put("bookedParcels",parcels.countByStatus(ParcelStatus.BOOKED));m.put("inTransitParcels",parcels.countByStatus(ParcelStatus.IN_TRANSIT));m.put("deliveredParcels",del);m.put("failedAttempts",attempts.countByAttemptStatus(AttemptStatus.FAILED));m.put("returnedParcels",parcels.countByStatus(ParcelStatus.RETURNED));m.put("activeDrivers",users.findByRoleAndStatus(UserRole.DRIVER,UserStatus.ACTIVE).size());m.put("deliverySuccessRate",total==0?0:Math.round(del*10000.0/total)/100.0);m.put("statusSummary",Arrays.stream(ParcelStatus.values()).map(s->Map.of("status",s.name(),"count",parcels.countByStatus(s))).toList());m.put("prioritySummary",Arrays.stream(ParcelPriority.values()).map(p->Map.of("priority",p.name(),"count",parcels.findAll().stream().filter(x->x.priority==p).count())).toList());return m;}Map<String,Object> driver(AppUser d){var l=parcels.findByAssignedDriver(d);return Map.of("assignedParcels",l.size(),"pickedUpCount",l.stream().filter(p->p.status==ParcelStatus.PICKED_UP).count(),"outForDeliveryCount",l.stream().filter(p->p.status==ParcelStatus.OUT_FOR_DELIVERY).count(),"deliveredToday",l.stream().filter(p->p.deliveredAt!=null&&p.deliveredAt.toLocalDate().equals(LocalDate.now())).count(),"failedAttemptsToday",attempts.countByDriverAndAttemptedAtBetween(d,LocalDate.now().atStartOfDay(),LocalDateTime.now()));}Map<String,Object> customer(AppUser c){var l=parcels.findByCustomer(c);return Map.of("myParcels",l.size(),"activeParcels",l.stream().filter(p->p.status!=ParcelStatus.DELIVERED&&p.status!=ParcelStatus.CANCELLED).count(),"deliveredParcels",l.stream().filter(p->p.status==ParcelStatus.DELIVERED).count(),"latestStatus",l.isEmpty()?"NO_PARCELS":l.get(l.size()-1).status.name());}}
